const tabId = 787784064;

// Let's inspect the page frames or inner editor element
const frameCheck = await browserjs(tabId, () => {
  const outerIframes = document.querySelectorAll('iframe');
  const result = [];
  for (const f of outerIframes) {
    try {
      const doc = f.contentDocument || f.contentWindow?.document;
      if (doc) {
        const innerIframes = doc.querySelectorAll('iframe');
        result.push({
          id: f.id,
          src: f.src,
          innerCount: innerIframes.length,
          bodyText: doc.body.innerText.slice(0, 100),
          hasCK: typeof f.contentWindow.CKEDITOR !== 'undefined'
        });
      }
    } catch (e) {
      result.push({ id: f.id, error: e.message });
    }
  }
  return result;
});
console.log("Frame check:", frameCheck);

